    public TardisData(UUID id, UUID ownerId, UUID exteriorId, String exterior, String interior, String dimension, BlockPos position, BlockPos interiorDoor, boolean interiorDoorStored, float yaw, boolean locked, boolean doorOpen, boolean powered, boolean refueling, boolean interiorInitialized, String doorAnimation, String dematAnimation, String matAnimation, TardisTravelState travelState, int phaseTicks, int flightTicks, int targetFlightTicks, String travelSourceDimension, BlockPos travelSourcePosition, float travelSourceYaw, String travelDestinationDimension, BlockPos travelDestinationPosition, float travelDestinationYaw) {
        this(id, ownerId, exteriorId, exterior, interior, dimension, position, interiorDoor, interiorDoorStored, yaw, locked, doorOpen, powered, refueling, interiorInitialized, doorAnimation, dematAnimation, matAnimation, travelState, phaseTicks, flightTicks, targetFlightTicks, travelSourceDimension, travelSourcePosition, travelSourceYaw, travelDestinationDimension, travelDestinationPosition, travelDestinationYaw, 0, false, TardisFuelManager.DEFAULT_MAX_FUEL, TardisFuelManager.DEFAULT_MAX_FUEL, 0.0D, false, 1, FlightCondition.NORMAL, FlightFailureType.NONE, "", travelDestinationDimension, travelDestinationPosition, travelDestinationYaw, "", "", 0, 0, 0, false, "", false);
    }

    public TardisData sanitized() {
        TardisTravelState state = travelState == null ? TardisTravelState.LANDED : travelState;
        FlightCondition condition = flightCondition == null ? FlightCondition.NORMAL : flightCondition;
        FlightFailureType failure = lastFailureType == null ? FlightFailureType.NONE : lastFailureType;
        int stage = Math.clamp(throttleStage, 0, 4);
        boolean missingCapacity = !Double.isFinite(maxFuel) || maxFuel <= 0.0D;
        double capacity = missingCapacity ? TardisFuelManager.DEFAULT_MAX_FUEL : maxFuel;
        double amount = Double.isFinite(fuel) ? Math.clamp(fuel, 0.0D, capacity) : capacity;
        if (missingCapacity && fuel == 0.0D) amount = capacity;
        double cost = state == TardisTravelState.LANDED || !Double.isFinite(travelFuelCost) || travelFuelCost < 0.0D ? 0.0D : travelFuelCost;
        boolean committed = state != TardisTravelState.LANDED && fuelCommitted;
        BlockPos requestedPosition = requestedDestinationPosition == null ? travelDestinationPosition : requestedDestinationPosition;
        String requestedDimension = requestedDestinationDimension == null ? travelDestinationDimension : requestedDestinationDimension;
        float requestedYaw = requestedDestinationDimension == null ? travelDestinationYaw : requestedDestinationYaw;
        return copy(exteriorId, exterior, interior, dimension, position, interiorDoor, interiorDoorStored, yaw, locked, doorOpen, powered, refueling, interiorInitialized, doorAnimation, dematAnimation, matAnimation, state, Math.max(0, phaseTicks), Math.max(0, flightTicks), Math.max(0, targetFlightTicks), travelSourceDimension, travelSourcePosition, travelSourceYaw, travelDestinationDimension, travelDestinationPosition, travelDestinationYaw, stage, handbrakeEngaged, amount, capacity, cost, committed, Math.max(1, dataVersion), condition, failure, lastFailureDetails, requestedDimension, requestedPosition, requestedYaw, activeFlightEvent, activeEventControl, Math.max(0, activeEventRemaining), Math.max(0, activeEventElapsed), Math.max(0, activeEventStep), activeEventConsequenceApplied, activeEventData, autopilot);
    }

