    public int getThrottleStage() { return throttleStage; }
    public boolean isCrashed() { return flightCondition == FlightCondition.CRASHED; }
    public boolean canUseNormalFlightControls() { return TardisCrashManager.canUseNormalFlightControls(this); }
    public TardisData withAutopilot(boolean value) { return copy(exteriorId, exterior, interior, dimension, position, interiorDoor, interiorDoorStored, yaw, locked, doorOpen, powered, refueling, interiorInitialized, doorAnimation, dematAnimation, matAnimation, travelState, phaseTicks, flightTicks, targetFlightTicks, travelSourceDimension, travelSourcePosition, travelSourceYaw, travelDestinationDimension, travelDestinationPosition, travelDestinationYaw, throttleStage, handbrakeEngaged, fuel, maxFuel, travelFuelCost, fuelCommitted, dataVersion, flightCondition, lastFailureType, lastFailureDetails, requestedDestinationDimension, requestedDestinationPosition, requestedDestinationYaw, activeFlightEvent, activeEventControl, activeEventRemaining, activeEventElapsed, activeEventStep, activeEventConsequenceApplied, activeEventData, value); }
