    public TardisData withFailure(FlightFailureType type, String details) { return copy(exteriorId, exterior, interior, dimension, position, interiorDoor, interiorDoorStored, yaw, locked, doorOpen, powered, refueling, interiorInitialized, doorAnimation, dematAnimation, matAnimation, travelState, phaseTicks, flightTicks, targetFlightTicks, travelSourceDimension, travelSourcePosition, travelSourceYaw, travelDestinationDimension, travelDestinationPosition, travelDestinationYaw, throttleStage, handbrakeEngaged, fuel, maxFuel, travelFuelCost, fuelCommitted, dataVersion, flightCondition, type, details, requestedDestinationDimension, requestedDestinationPosition, requestedDestinationYaw, activeFlightEvent, activeEventControl, activeEventRemaining, activeEventElapsed, activeEventStep, activeEventConsequenceApplied, activeEventData); }
