    public TardisData withFlightEvent(String id, String control, int remaining, int elapsed, int step, boolean consequenceApplied, String eventData) { return copy(exteriorId, exterior, interior, dimension, position, interiorDoor, interiorDoorStored, yaw, locked, doorOpen, powered, refueling, interiorInitialized, doorAnimation, dematAnimation, matAnimation, travelState, phaseTicks, flightTicks, targetFlightTicks, travelSourceDimension, travelSourcePosition, travelSourceYaw, travelDestinationDimension, travelDestinationPosition, travelDestinationYaw, throttleStage, handbrakeEngaged, fuel, maxFuel, travelFuelCost, fuelCommitted, dataVersion, flightCondition, lastFailureType, lastFailureDetails, requestedDestinationDimension, requestedDestinationPosition, requestedDestinationYaw, id, control, remaining, elapsed, step, consequenceApplied, eventData); }
